{
  "cards": [
    {
      "front": "What is the Ohm's law relationship for an ideal DC resistive circuit, including the units of $V$, $I$, and $R$?",
      "back": "Ohm's law is $V = IR$, where $V$ is voltage in volts, $I$ is current in amperes, and $R$ is resistance in ohms."
    ,
    "topic": "Ohm's law"
    },
    {
      "front": "For two series resistors of $2\\ \\Omega$ and $4\\ \\Omega$ connected to a $12\\ \\text{V}$ source, what is the current through the circuit?",
      "back": "The equivalent resistance is $R_{eq} = 2 + 4 = 6\\ \\Omega$, so the current is $I = V/R_{eq} = 12/6 = 2\\ \\text{A}$."
    ,
    "topic": "Ohm's law"
    }
  ]
}

{
  "cards": [
    {
      "front": "In a series resistor circuit, what is true about the current through each resistor, and how is the equivalent resistance calculated?",
      "back": "The same current flows through all resistors in series. The equivalent resistance is the sum of the individual resistances: $R_{eq}=R_1+R_2+\\cdots$."
    ,
      "topic": "Series resistor circuits"
    },
    {
      "front": "Two series resistors of $2\\ \\Omega$ and $4\\ \\Omega$ are connected to a $12\\ \\text{V}$ source. What are the equivalent resistance, current, and voltage drops across the resistors?",
      "back": "$R_{eq}=2+4=6\\ \\Omega$. The current is $I=V/R_{eq}=12/6=2\\ \\text{A}$. The voltage drops are $V_1=IR_1=(2)(2)=4\\ \\text{V}$ and $V_2=IR_2=(2)(4)=8\\ \\text{V}$, which sum to the $12\\ \\text{V}$ source voltage."
    ,
      "topic": "Series resistor circuits"
    }
  ]
}

{
  "cards": [
    {
      "front": "What is the relationship used to find the equivalent resistance of resistors connected in parallel?",
      "back": "The reciprocal of the equivalent resistance equals the sum of the reciprocals of the branch resistances: $1/R_{eq} = 1/R_1 + 1/R_2 + \\cdots$."
    ,
      "topic": "Parallel resistor circuits"
    },
    {
      "front": "What must be stated before comparing power dissipation in two resistors?",
      "back": "You must state which quantity is fixed. At fixed voltage, a smaller resistance dissipates more power; at fixed current, a larger resistance dissipates more power."
    ,
      "topic": "Parallel resistor circuits"
    }
  ]
}

{
  "cards": [
    {
      "front": "For an ideal resistor, what are the three equivalent expressions for power dissipation in terms of voltage, current, and resistance, and what are the units?",
      "back": "The power dissipated by an ideal resistor is $P = VI = I^2 R = V^2/R$. The unit of power is the watt, $\\text{W}$."
    ,
      "topic": "Resistor power dissipation"
    },
    {
      "front": "When comparing the power dissipated by two resistors, what must you state first, and how does the comparison differ when voltage is fixed versus when current is fixed?",
      "back": "You must state which quantity is fixed before comparing power. At fixed voltage, a smaller resistance dissipates more power because $P = V^2/R$. At fixed current, a larger resistance dissipates more power because $P = I^2 R$."
    ,
      "topic": "Resistor power dissipation"
    }
  ]
}

{
  "cards": [
    {
      "front": "How is an ideal ammeter connected in a circuit?",
      "back": "An ideal ammeter is inserted in series with the branch or element whose current $I$ is to be measured."
    ,
      "topic": "Ideal meter connections"
    },
    {
      "front": "How is an ideal voltmeter connected in a circuit?",
      "back": "An ideal voltmeter is connected in parallel across the element or two points whose voltage $V$ is to be measured."
    ,
      "topic": "Ideal meter connections"
    }
  ]
}

